# -*- coding: utf-8 -*-
"""Темы 5–7: категория состояния, предлог, союз."""
from h import *

TOPICS = []

# ============================================================ КАТЕГОРИЯ СОСТОЯНИЯ
TOPICS.append(dict(
 slug='state', icon='🌡️', title='Категория состояния',
 lead='Слова «тихо», «жаль», «пора», «холодно», «нельзя»: они сообщают, в каком состоянии что-то находится. Выглядят как наречия — но это особая группа слов с другой ролью в предложении.',
 sections=[
 ('Что это за слова', '''
<p>Посмотри на предложения:</p>
''' + EX('<i>На улице <b>холодно</b>.</i>', '<i>Мне <b>грустно</b>.</i>', '<i>В комнате <b>тихо</b>.</i>', '<i>В школе <b>нельзя</b> бегать.</i>', '<i><b>Пора</b> идти домой.</i>') + '''
<p>Во всех этих предложениях нет подлежащего — то есть нет слова, которое отвечало бы на вопрос «кто? что?» и «выполняло» состояние. «Холодно» не про кого-то конкретного, а просто про обстановку: <i>вообще холодно</i>. Такие предложения называются <b>безличными</b>, а слова «холодно», «грустно», «нельзя» — <b>категория состояния</b>.</p>
''' + SAY('Категория состояния (КС) — слова, которые называют <b>состояние</b>: природы (<i>светло, тепло, ветрено</i>), человека (<i>весело, стыдно, страшно</i>), окружающей обстановки (<i>душно, тихо</i>) или выражают <b>необходимость, возможность</b>, оценку (<i>можно, нельзя, надо, пора, жаль, лень</i>). Они отвечают на вопрос «как?» и в предложении почти всегда — <b>сказуемое</b>.') + T(
 ['состояние природы', '<i>светло, морозно, пасмурно, ветрено</i>', '<i>За окном <b>морозно</b>.</i>'],
 ['состояние человека', '<i>весело, стыдно, обидно, радостно</i>', '<i>Ей <b>обидно</b>.</i>'],
 ['состояние обстановки', '<i>тихо, душно, людно, пусто</i>', '<i>В классе <b>душно</b>.</i>'],
 ['необходимость, возможность, оценка', '<i>надо, нужно, нельзя, можно, пора, жаль, лень</i>', '<i><b>Нельзя</b> опаздывать.</i>'],
 head=['Что называют', 'Примеры', 'В предложении'])),

 ('Как отличить КС от наречия и краткого прилагательного', '''
<p>Самое неприятное в этой теме: слова-«двойники». «Тихо» может быть наречием, а может быть КС. Всё зависит от предложения. Есть простая схема-проверка.</p>
''' + STEPS('Три вопроса к слову',
 'Есть ли в предложении <b>подлежащее</b>, о котором говорится «каков? какова? каково?»? Если слово можно согласовать с ним по роду — это <b>краткое прилагательное</b>: <i>Вечер тих, ночь тиха, утро тихо</i>.',
 'Если слово относится к <b>глаголу</b> и отвечает «как?» — это <b>наречие</b>: <i>Она тихо вошла</i> (как вошла?).',
 'Если подлежащего нет, слово — сказуемое (<i>В доме тихо</i>, <i>Мне жаль</i>, <i>Пора идти</i>) — это <b>категория состояния</b>.') + T(
 ['Она <b>тихо</b> вошла в комнату.', 'наречие', 'относится к глаголу «вошла» (как вошла?)'],
 ['В доме было <b>тихо</b>.', 'категория состояния', 'подлежащего нет, слово — сказуемое'],
 ['Вечер <b>тих</b> и спокоен.', 'краткое прилагательное', 'есть подлежащее «вечер», слово изменяется (тих, тиха)'],
 head=['Предложение', 'Часть речи', 'Почему']) + '''
''' + DEMO('«Мне искренне жаль потраченного времени»',
 '«Жаль» — слово о состоянии человека («мне жаль»).',
 'Подлежащего нет. «Мне» — дополнение, не подлежащее.',
 'К глаголу «жаль» не относится. → <b>категория состояния</b>.') + DEMO('«Уже пора идти домой»',
 'Есть слово «пора» — это не существительное (как в «пора цветения»), а оценка времени: «пора что делать?» — идти.',
 'Подлежащего нет. → <b>категория состояния</b>.') + TIP('Обрати внимание на слова, к которым можно «приклеить» инфинитив: <i>пора идти, нельзя курить, надо учиться, лень вставать, жаль расставаться</i>. Почти всегда это КС.') + WARN('Не все слова на -о — категория состояния. <i>Быстро, хорошо, громко</i> — как правило, наречия (они описывают действие). КС — только те, что описывают общее состояние и работают как сказуемое без подлежащего.') + RECAP(
 'КС называет состояние природы, человека, обстановки или необходимость/возможность (<i>надо, нельзя, жаль</i>).',
 'В предложении КС — сказуемое в безличном предложении, подлежащего нет.',
 'Отличие от наречия: наречие относится к глаголу; отличие от краткого прилагательного: у того есть подлежащее.')),
 ],
 quiz=[
  Q('Какой частью речи является слово «жаль» в предложении «Мне искренне жаль потраченного времени»?', ['глагол','наречие','категория состояния'], 2, 'Слово называет состояние человека и служит сказуемым без подлежащего.'),
  Q('В каком предложении слово «тихо» — категория состояния?', ['Она тихо вошла в комнату.','В доме было тихо.','Вечер тих и спокоен.'], 1, 'В безличном предложении «В доме было тихо» нет подлежащего, слово называет состояние.'),
  Q('Какой частью речи является слово «пора» в предложении «Уже пора идти домой»?', ['существительное','наречие','категория состояния'], 2, 'Слово выражает оценку времени и является сказуемым безличного предложения.'),
  Q('Что из перечисленного НЕ является категорией состояния?', ['нельзя','грустно','быстро'], 2, '«Быстро» отвечает на вопрос «как?» и описывает действие — это наречие. Остальные слова называют состояние.'),
 ]))

# ============================================================ ПРЕДЛОГ
TOPICS.append(dict(
 slug='preposition', icon='🔗', title='Предлог',
 lead='Маленькие слова «в», «на», «из-за», «благодаря», которые показывают, как слова в предложении связаны друг с другом.',
 sections=[
 ('Зачем нужны предлоги', '''
<p>Сравни три фразы: <i>книга <b>на</b> столе</i>, <i>книга <b>под</b> столом</i>, <i>книга <b>за</b> столом</i>. Меняется только маленькое слово, а смысл — совсем другой. Это и есть предлог.</p>
''' + SAY('Предлог — служебное слово, которое показывает <b>связь</b> между существительным (или местоимением, числительным) и другими словами: где (<i>на столе</i>), куда (<i>в школу</i>), когда (<i>после урока</i>), почему (<i>из-за дождя</i>). Предлог <b>не изменяется</b> и сам <b>не является членом предложения</b> — он только «клей».') + '''
<h3>Простые, производные, составные</h3>
''' + T(
 ['<b>Простые</b>', 'состоят из одного слова и не образованы от других частей речи', '<i>в, на, за, под, из, к, у, при, о, от</i>'],
 ['<b>Производные</b>', 'образованы от других частей речи (существительных, наречий, глаголов)', '<i>благодаря, вследствие, несмотря на, согласно, вокруг, около</i>'],
 ['<b>Составные</b>', 'из нескольких слов', '<i>в течение, в связи с, по причине, в соответствии с, в отличие от</i>'],
 head=['Вид', 'Что это', 'Примеры']) + TIP('Производный предлог часто можно «расшифровать»: <i>благодаря</i> ← благодарить (деепричастие), <i>вследствие</i> ← следствие, <i>в течение</i> ← течение. Поэтому их и путают с обычными словами.')),

 ('Как пишутся производные предлоги', '''
<p>Проблема в том, что многие производные предлоги похожи на обычные слова: «в течение» — «в течении реки», «вследствие» — «следствие». Разберём самые частые случаи.</p>
<h3>Слитно или раздельно</h3>
''' + T(
 ['<b>слитно</b>', '<i>ввиду, вследствие, наподобие, насчёт, навстречу, несмотря на, благодаря</i>'],
 ['<b>раздельно</b>', '<i>в течение, в продолжение, в связи с, в отличие от, в соответствии с, по причине, в силу, в заключение</i>'],
 head=['Как пишем', 'Примеры']) + TIP('Почти все составные предлоги пишутся раздельно, потому что состоят из двух-трёх слов: <i>в связи с, в отличие от</i>. А производные, образованные от одного слова, — слитно: <i>вследствие, ввиду, насчёт</i>.') + '''
<h3>Предлог или существительное с предлогом?</h3>
<p>Здесь помогает замена: если можно подставить <b>«из-за»</b>, <b>«в течение»</b>, <b>«о»</b> — перед тобой предлог. Если можно поставить определение или вопрос — это существительное.</p>
''' + T(
 ['<i>Мы ждали <b>в течение</b> часа.</i> (= на протяжении)', '<i>Лодка плыла <b>в течении</b> реки.</i> (в чём? в какой реке?)', 'В течение (предлог) — окончание <b>-е</b>. В течении (существительное, предложный падеж) — <b>-и</b>.'],
 ['<i><b>Вследствие</b> аварии перекрыли дорогу.</i> (= из-за)', '<i>В <b>следствии</b> по делу появились новые факты.</i> (в чём?)', 'Предлог — слитно. Существительное — два слова.'],
 ['<i><b>Несмотря на</b> дождь, мы пошли гулять.</i>', '<i><b>Не смотря</b> на экран, он слушал.</i> (не глядя)', 'Предлог пишется слитно, а деепричастие — раздельно.'],
 head=['Предлог', 'Существительное / другая часть речи', 'Правило']) + '''
''' + RULE('Предлог на «-ие»: <b>в течение, в продолжение, в заключение</b> — оканчивается на <b>-е</b>. Существительное с предлогом «в»: в течении, в продолжении, в заключении — на <b>-и</b>.') + '''
<h3>Дефис в предлогах</h3>
<p>Через дефис пишутся только три предлога: <b>из-за, из-под, по-над</b>: <i>выйти из-за угла, достать из-под стола</i>.</p>'''),

 ('Падеж после предлога: чтобы не говорить «согласно приказа»', '''
<p>Каждый предлог «требует» своего падежа: <i>в (чём?) доме, к (чему?) дому</i>. Особенно часто ошибаются с производными предлогами. Вот те, что нужно просто запомнить.</p>
''' + T(
 ['<b>благодаря</b>', 'кому? чему? (дат.)', '<i>благодаря другу, благодаря помощи</i>'],
 ['<b>согласно</b>', 'чему? (дат.)', '<i>согласно приказу</i> (не <s>приказа</s>), <i>согласно расписанию</i>'],
 ['<b>вопреки</b>', 'чему? (дат.)', '<i>вопреки прогнозу</i> (не <s>прогноза</s>)'],
 ['<b>по</b> (в значении «после»)', 'о чём? (предл.)', '<i>по приезде, по окончании, по прибытии</i> (не <s>по приезду</s>)'],
 ['<b>несмотря на</b>', 'на что? (вин.)', '<i>несмотря на дождь</i>'],
 head=['Предлог', 'Падеж', 'Пример']) + '''
<p>Ещё типичная речевая ошибка — путаница между «оплатить» и «заплатить»:</p>
''' + EX('<i>оплатить <b>проезд</b></i>, но <i>заплатить <b>за проезд</b></i>', '<i>рецензия <b>на</b> фильм</i>, но <i>отзыв <b>о</b> фильме</i>') + '''
<h3>«Из-за» или «благодаря»?</h3>
<p>Предлоги <b>из-за</b> и <b>благодаря</b> обозначают причину, но по-разному.</p>
''' + T(
 ['<b>из-за</b>', 'причина плохая или нейтральная', '<i>Из-за метели рейс задержали.</i>'],
 ['<b>благодаря</b>', 'причина хорошая, есть «спасибо»', '<i>Благодаря тренеру мы выиграли.</i>'],
 head=['Предлог', 'Когда', 'Пример']) + WARN('«<s>Благодаря дождю</s> мы промокли» звучит странно: благодарить за дождь не за что. Пиши «из-за дождя».') + RECAP(
 'Предлог показывает связь слов; не изменяется и не является членом предложения.',
 'Производные предлоги: <i>вследствие, ввиду, насчёт</i> — слитно; <i>в течение, в связи с, в отличие от</i> — раздельно.',
 'В течение (предлог) — на -е; в течении реки (сущ.) — на -и.',
 'Из-за, из-под, по-над пишем через дефис.',
 'Благодаря, согласно, вопреки — с дательным падежом; по приезде (а не по приезду).')),
 ],
 quiz=[
  Q('Как пишется: «Я ждал ответа в течени… часа»?', ['в течение','в течении','втечение'], 0, 'Это производный предлог времени (= на протяжении часа): пишется раздельно и оканчивается на -е.'),
  Q('В каком предложении «вследствие» пишется слитно?', ['(В)следстви… аварии перекрыли дорогу.','(В)следстви… по делу появились новые факты.'], 0, 'В первом предложении это предлог причины (= из-за). Во втором — существительное «следствие» с предлогом «в».'),
  Q('Выберите верный вариант:', ['согласно расписания','согласно расписанию','согласно к расписанию'], 1, 'Предлог «согласно» употребляется с дательным падежом: согласно чему? — расписанию.'),
  Q('Как правильно: «По (приезде/приезду) домой я позвонил маме»?', ['по приезде','по приезду'], 0, 'Предлог «по» в значении «после» требует предложного падежа: по приезде.'),
  Q('Как пишется: «(Не)смотря на дождь, мы пошли гулять»?', ['несмотря (слитно)','не смотря (раздельно)'], 0, 'Это производный предлог — пишется слитно.'),
  Q('Как пишется: «выйти из…за угла»?', ['из-за','из за','изза'], 0, 'Предлог из-за пишется через дефис.'),
  Q('Какое слово уместно: «… метели рейс задержали»?', ['Благодаря','Из-за'], 1, 'Причина нежелательная — нужно «из-за». «Благодаря» используют, когда причина хорошая.'),
 ]))

# ============================================================ СОЮЗ
TOPICS.append(dict(
 slug='conjunction', icon='🌉', title='Союз',
 lead='«И», «а», «но», «что», «потому что», «чтобы» — слова-мосты, которые соединяют части предложения. И пара «ловушек» в написании: тоже/то же, чтобы/что бы, зато/за то.',
 sections=[
 ('Что такое союз', '''
<p>Представь два берега и мост между ними. Союз и есть такой мост: он соединяет слова или целые части предложения.</p>
''' + EX('<i>Я люблю чай <b>и</b> кофе.</i> (соединяет слова)', '<i>Солнце село, <b>и</b> стало темно.</i> (соединяет части предложения)', '<i>Я знаю, <b>что</b> ты прав.</i> (одна часть зависит от другой)') + SAY('Союз — служебное слово: не изменяется, не является членом предложения и <b>только соединяет</b> однородные члены предложения или части сложного предложения.') + '''
<h3>Два главных вида союзов</h3>
''' + T(
 ['<b>Сочинительные</b>', 'соединяют <b>равноправные</b> части: можно переставить местами или отделить точкой', '<i>и, а, но, или, да, однако, зато, либо</i>'],
 ['<b>Подчинительные</b>', 'одна часть зависит от другой («главная» и «зависимая»): к зависимой части можно задать вопрос', '<i>что, чтобы, если, когда, потому что, так как, хотя, как</i>'],
 head=['Вид', 'Как работает', 'Союзы']) + '''
<h3>Сочинительные союзы бывают трёх типов</h3>
''' + T(
 ['<b>соединительные</b>', 'и, да (= и), тоже, также, ни…ни', '<i>Он пел <b>и</b> играл на гитаре.</i>'],
 ['<b>противительные</b>', 'а, но, да (= но), однако, зато', '<i>Дождь шёл, <b>но</b> мы пошли гулять.</i>'],
 ['<b>разделительные</b>', 'или, либо, то…то, не то…не то', '<i>Он <b>то</b> смеялся, <b>то</b> грустил.</i>'],
 head=['Тип', 'Союзы', 'Пример']) + '''
<p>Подчинительные союзы бывают простые (<i>что, если, когда</i>) и составные (<i>потому что, так как, для того чтобы, в то время как</i>).</p>''' ),

 ('Союзы и запятые', '''
<p>Коротко о том, где нужны запятые.</p>
''' + T(
 ['перед <b>а</b>, <b>но</b>, <b>однако</b>, <b>зато</b>', 'всегда', '<i>Он старался<b>,</b> но не успел.</i>'],
 ['перед подчинительным союзом (<b>что, чтобы, если, когда…</b>)', 'всегда', '<i>Я знаю<b>,</b> что ты прав.</i>'],
 ['перед <b>и</b> между однородными словами', 'не нужна', '<i>Я люблю чай и кофе.</i>'],
 ['перед <b>и</b> между частями сложного предложения (у каждой своя основа)', 'нужна', '<i>Солнце село<b>,</b> и стало темно.</i>'],
 head=['Где', 'Запятая', 'Пример']) + '''
''' + TIP('Чтобы понять, ставить ли запятую перед «и», посмотри, <b>сколько «героев» и действий</b>. Если у каждой части свои подлежащее и сказуемое («солнце село», «стало темно»), перед «и» запятая нужна. Если «и» просто соединяет два слова («чай и кофе») — не нужна.')),

 ('Слитно или раздельно: союзы-двойники', '''
<p>В русском есть пары «двойников»: союз пишется слитно, а похожее сочетание слов — раздельно. Чтобы не путаться, пользуйся подстановкой.</p>
''' + T(
 ['<b>также</b> (= и)', '<b>так же</b> (= таким же образом)', '<i>Я <b>также</b> хочу пойти</i> (= и я хочу). <i>Он смеётся <b>так же</b>, как ты</i> (= так же).'],
 ['<b>тоже</b> (= и)', '<b>то же</b> (= то самое)', '<i>Я <b>тоже</b> пойду</i> (= и я). <i>Он сказал <b>то же</b> самое</i>.'],
 ['<b>чтобы</b> (цель)', '<b>что бы</b> (что + бы)', '<i>Я пришёл, <b>чтобы</b> помочь.</i> <i><b>Что бы</b> мне подарить?</i> (можно убрать «бы»)'],
 ['<b>зато</b> (= но)', '<b>за то</b> (за что?)', '<i>Фильм длинный, <b>зато</b> интересный.</i> <i>Спасибо <b>за то</b>, что помог.</i>'],
 ['<b>оттого</b> (= поэтому)', '<b>от того</b> (от чего?)', '<i>Он болен, <b>оттого</b> и грустит.</i> <i>Всё зависит <b>от того</b>, что скажет врач.</i>'],
 head=['Союз (слитно)', 'Сочетание (раздельно)', 'Примеры']) + '''
''' + STEPS('Как отличить за 10 секунд',
 '<b>Тоже / также</b> — замени на <b>«и»</b>. Получилось? Пиши слитно: <i>Я тоже пойду → И я пойду</i>.',
 '<b>Чтобы</b> — замени на «для того чтобы». Получилось? Пиши слитно. Если можно убрать «бы» или переставить его — это «что бы».',
 '<b>Зато</b> — замени на <b>«но»</b>: <i>длинный, но интересный</i>. Получилось? Слитно.',
 '<b>Оттого</b> — замени на «поэтому» или «потому». Получилось? Слитно.') + DEMO('Я пришёл, (что бы/чтобы) помочь',
 'Заменяем на «для того чтобы»: «Я пришёл, для того чтобы помочь» — работает.',
 'Значит, это союз, пишем слитно: <b>чтобы</b>.') + RECAP(
 'Союзы соединяют слова и части предложения; бывают сочинительные (и, а, но) и подчинительные (что, если, чтобы).',
 'Перед «а», «но» и подчинительными союзами запятая нужна; перед одиночным «и» между однородными словами — нет.',
 'Тоже, также, зато, чтобы, оттого пишем слитно, если слово заменяется на «и», «но», «для того чтобы», «поэтому».')),
 ],
 quiz=[
  Q('В каком предложении «тоже» пишется слитно?', ['Я сделал то же самое.','Мой друг играет в шахматы, я тоже играю.','Что же ты молчишь?'], 1, '«Тоже» заменяется союзом «и»: и я играю. Во втором случае — местоимение «то» с частицей.'),
  Q('Какое предложение написано грамотно?', ['Что бы мне подарить маме?','Чтобы мне подарить маме?','Что-бы мне подарить маме?'], 0, 'Здесь «что» — местоимение, «бы» — частица (можно убрать: «Что мне подарить маме?»).'),
  Q('Как пишется: «Я пришёл, (что бы/чтобы) помочь»?', ['что бы','чтобы'], 1, 'Это союз цели («для того чтобы»), он пишется слитно.'),
  Q('Как пишется: «Фильм длинный, (за)то интересный»?', ['зато (слитно)','за то (раздельно)'], 0, 'Слово можно заменить на «но»: длинный, но интересный.'),
  Q('Как пишется: «Спасибо (за)то, что помог»?', ['зато','за то'], 1, 'Это предлог «за» и местоимение «то»: за что? За то, что помог.'),
  Q('Где перед «и» нужна запятая?', ['Я люблю чай и кофе.','Солнце село и стало темно.','Он пел и играл на гитаре.'], 1, 'Во втором предложении две части с разными героями: «Солнце село, и стало темно».'),
 ]))
